// === Tab: mySketch ===
// by SamuelYAN
// more works //
// https://twitter.com/SamuelAnn0924
// https://www.instagram.com/samuel_yan_1990/

// genuary 2024
// JAN. 22 (credit: Paolo Curtoni)
// Point - line - plane

let seed = Math.random() * 99999;
let mySize, margin, space;
let lefr_h, lefr_r;
let xspacing, w, maxwaves, theta;
let amplitude = new Array(maxwaves);
let dx = new Array(maxwaves);
let yvalues;
let palette;

function setup() {
	// pixelDensity(4);
	frameRate(50);
	randomSeed(seed);
	mySize = max(windowWidth, windowHeight) * 0.8;
	if (mySize > 800) {
		mySize = 800;
	}
	margin = mySize / 100;
	createCanvas(mySize, mySize);
	makeFilter();
	makeFilter2();

	palette = random(colorScheme).colors.concat();
	background(random(palette));

	w = width * random(1.25, 0.75);
	m = 0;
	lefr_h = random(0.75, 1.45);
	lefr_r = random(0.45, 0.55);
	xspacing = int(random(4, 8)) * random([2, 10, 5]) / 50;
	maxwaves = 10 * int(random(12, 3));
	theta = 0.0;
	amplitude = new Array(maxwaves);
	dx = new Array(maxwaves);
	for (let i = 0; i < maxwaves; i++) {
		amplitude[i] = random(10, 5);
		let period = int(random(50, 10));
		dx[i] = (TWO_PI / period) * xspacing /random(2,20);
	}
	yvalues = new Array(int(w / xspacing * 1));
}

function draw() {
	randomSeed(seed);
	// background(random(palette));
	push();
	translate(width / 2, height / 2 );
	// rotate(-PI / random(1.5, 2.5) + random(-PI / 6, PI / 6));
	rotate(random(0, TAU));
	strokeCap(PROJECT);

	let ttt = random([2, 3]);
	for (let i = -xspacing * ttt; i < xspacing * ttt; i += 1*int(random(4, 16))) {
		push();
		translate(i - m, i * m + m);
		calcWave();
		renderWave();
		pop();
	}
	pop();
	// m -= random(0.08, 0.15) / random(2, 10);
	image(overAllTexture2, 0, 0);
}

function calcWave() {
	for (let i = 0; i < yvalues.length; i++) {
		yvalues[i] = 0;
	}
	for (let j = 0; j < maxwaves; j++) {
		let x = theta;
		for (let i = 0; i < yvalues.length; i++) {
			if (j % 2 == 0) yvalues[i] += sin(x + m) * amplitude[j];
			else yvalues[i] += cos(x) * amplitude[j];
			x += dx[j];
		}
	}
	theta += random(0.002, 0.005) / random(0.1, 0.5);
}

function renderWave() {
	noFill();
	for (let x = 0; x < yvalues.length; x++) {
		// stroke(random(palette));
		stroke(str(random(palette)) + random(["bf", "33", "80", "40"]));
		strokeWeight(mySize/200 * random(1, 2) * random([0.75, 0.25, 0.5]));
		drawingContext.shadowColor = str(random(palette)) + random(["bf", "33", "80", "40"]);
		drawingContext.shadowOffsetX = 1.5;
		drawingContext.shadowOffsetY = 1.5;
		drawingContext.shadowBlur = 0;
		beginShape();
		vertex(-random(width, width) + x * xspacing, 0 + yvalues[x]);
		vertex(width * lefr_h / 1.5 + x * xspacing, height / 1);
		vertex(-random(0, 0) + x * xspacing, 0 + yvalues[x]);
		endShape();
	}

	for (let x = 0; x < yvalues.length; x++) {
		drawingContext.shadowColor = str(random(palette)) + "80";
		drawingContext.shadowOffsetX = 0.5;
		drawingContext.shadowOffsetY = 0.5;
		drawingContext.shadowBlur = 0;
		if (int(x) % random([5, 10, 15, 20]) == 0) {
			stroke(random(palette));
			strokeWeight(random(1, 3) * random(1, 3) * random([0.1, 0.25, 0.5]));
		}

		stroke(random(palette));
		strokeWeight(random(mySize) / random(8, 3) * random([0.1, 0.25, 0.5]));
		point(-width + x * xspacing, 0 + yvalues[x]);
	}
}

